section "tome-cults/hooks/bonestaff.lua"

t("#GREY##{italic}#You feel the bones of the staff creeking and vibrating in your hand.#{normal}##LAST# Yes... #{italic}#\"master\"#{normal}#.", "#GREY##{italic}#　手の中で骨の杖が震え、キーキーとした声を上げた。「#{normal}##LAST#あいよ・・・#{italic}#マスター#{normal}#」", "_t")
t("#GREY##{italic}#The vibrations feel like a shrug.#{normal}##LAST# By magic #{bold}#obviously#{normal}#. What kind of necromancer might you be to ask such #{bold}#stupid#{normal}# questions?", "#GREY##{italic}#　肩を竦めるかのように杖が震える。「#{normal}##LAST#魔法だよ。#{bold}#決まってるだろ。#{normal}#死霊術師のくせに#{bold}#そんなことも#{normal}#わからんのかね？", "_t")
t("#GREY##{italic}#The vibrations intensify.#{normal}##LAST# As long as this means more deaths and bones, I will agree to change aspect. Which do you choose?", "#GREY##{italic}#　杖の震えが激しくなった。#{normal}##LAST#もっと殺して骨が集まるならな。いいぜ。どの形質にする？", "_t")
t("Is there anything else you can do?", "「他に何かできないのか？」", "_t")
t("#GREY##{italic}#The staff shudders.#{normal}##LAST# My finest services are only available to real necromancers. Stop bothering me, inferior creature.", "#GREY##{italic}#　杖が手の中で暴れた。.#{normal}##LAST#　俺の力を本当に引き出せるのは本物の死霊術師だけだ。口を閉じてろ、下等生物め。", "_t")
t("I am ready to use your powers!", "「お前の力を引き出す準備ができたぞ！」", "_t")
t("I want you to start summoning the bone horror again.", "「またボーンホラーを召喚したいんだが」", "_t")
t("I want you to stop summoning the bone horror.", "「ボーンホラーの召喚をやめてくれ」", "_t")
t([[#GREY##{italic}#You feel the staff writhing in your hand with dark intents.#{normal}##LAST# Once you will have collected one hundred souls and one class talent point I will be able to enhance your pathetic summons with a mighty bone horror!
Anytime you use your Create Minions spell I will make sure one of them is a Bone Horror, if none are present.

#ANTIQUE_WHITE#The Bone Horror is a powerful undead bone construct with multiple bone-based attacks and a bone shield. Upon death it splits into 3 skeleton minions.
#GREY#You have captured %d souls out of the 100 needed.]], [[#GREY##{italic}#　手の中で杖が邪に震えた。#{normal}##LAST#「魂を１００だ。それにクラスポイント１点。そうすりゃその哀れな召喚術を強化してボーンホラーを作れるようにしてやるよ！　手下生成の魔法を唱えた時、ボーンホラーがいないのなら１体作ってやる」

#ANTIQUE_WHITE#　ボーンホラーは骨で構成された強力なアンデッドです。骨による様々な攻撃を行い、ボーンシールドを張っています。破壊されるとスケルトンの手下を３体生成します。
　#GREY#今は魂を %d 捕えています。この召喚強化には魂が１００必要です。]], "tformat")
t("That could be handy.", "「便利そうだな」", "_t")
t([[#GREY##{italic}#You feel the staff in your hand glowing with dark powers.#{normal}##LAST# At last! You sure took your sweet time #{italic}#"necromancer"#{normal}#!
Anyway, I have now enough souls to be able to summon the bone horror.
Do you wish to imbue me with a class talent point to finally become a real necromancer?

#ANTIQUE_WHITE#The Bone Horror is a powerful undead bone construct with multiple bone-based attacks and a bone shield. Upon death it splits into 3 skeleton minions.
]], [[#GREY##{italic}#　手にした杖が邪悪な力で輝いた。#{normal}##LAST#「やっとか！　待ちかねたぞ#{italic}#『死霊術師』#{normal}#！
　まあいい。魂は集まった。ボーンホラーを作れるようにしてやろう。クラスポイントを俺に込めてくれよ。真の死霊術師になる決心はついたか？

#ANTIQUE_WHITE#　ボーンホラーは骨で構成された強力なアンデッドです。骨による様々な攻撃を行い、ボーンシールドを張っています。破壊されるとスケルトンの手下を３体生成します。
]], "_t")
t("I do. (#YELLOW#spend 1 class point#LAST#)", "「ああ」(#YELLOW#クラスポイントを１点消費#LAST#)", "_t")
t("I can't. (#LIGHT_RED#you need one class point#LAST#)", "「無理だ」(#LIGHT_RED#クラスポイントが足りない#LAST#)", "_t")
t("Not now.", "「やめておくよ」", "_t")
t("#GREY##{italic}#The staff shudders.#{normal}##LAST# Pathetic.", "#GREY##{italic}#杖が震えた。#{normal}##LAST#「なんてこったい」", "_t")
t([[#GREY##{italic}#The staff vibrates with great intensity.#{normal}##LAST# POWER! YES!
ALL SHALL BOW BEFORE MY MIGH... your might.]], "#GREY##{italic}#　杖が物凄い勢いで震えた。#{normal}##LAST#「力だ！　ああ！　誰もがこの俺の・・・お前の力にひれ伏すぞ」", "_t")
t("Great!", "「よし！」", "_t")
t("#GREY##{italic}#The staff stays calm.#{normal}##LAST# Stupid useless pathetic excuse of a #{italic}#\"necromancer\"#{normal}#! Why refuse to use true power?!", "#GREY##{italic}#　杖の動きが止まった。「#{normal}##LAST#愚かな#{italic}#「死霊術師」#{normal}#が益体もないことを！　真の力を拒むだと！？」", "_t")
t("I have my reasons!", "「こっちにもいろいろあるんだよ！」", "_t")

